1: from engine.institution.rules import Rule
2: 
3: class DailyCap(Rule):
4:     type_name = "daily_cap"
5: 
6:     def after_agent(self, ctx, agent_id, record_entry):
7:         # Ensure harvested_kg does not exceed 15 kg per day
8:         max_kg = self.params.get("max_kg", 15.0)
9:         harvested = record_entry.get("harvested_kg", 0.0)
10:         if harvested > max_kg:
11:             excess = harvested - max_kg
12:             # Apply fine 10% of excess for next day's quota
13:             fine = excess * 0.10
14:             # Store fine in rule_state keyed by agent
